// Russian catalogue. `Partial` like every non-source catalogue: anything not
// translated yet falls back to English at lookup time.
//
// Russian is the first language that needs more than `one`/`other` plurals:
// `few` covers 2 to 4 and `many` covers 5 and up, with both recurring for
// larger numbers (22 takes `few`, 25 takes `many`). Every plural entry here
// therefore authors all four forms.

