  "settings.steam.trustCalls": "Клиент сообщает Steam только о начале и завершении игры в Forged Alliance. Steam узнаёт, какой аккаунт и когда играл, и показывает это вашим друзьям согласно настройкам приватности Steam. FAF это отдельный клиент: без этой настройки Steam не узнает, когда вы играете через FAF.",
