  "settings.game.cacheRollingBranchesDocOverview": "Плавающие ветки, такие как FAF Develop и FAF Beta, не имеют постоянных номеров версий на сервере. При публикации новых коммитов файлы перезаписываются, из-за чего старые повторы рассинхронизируются.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Снимки версий",
  "settings.game.cacheRollingBranchesDocHowDesc": "При включении каждая уникальная сборка определяется по Git SHA и хэшу файлов и добавляется в локальный манифест версий.",
